-- GENERATED by `wfj generate` from data/gossip/gossip-ef.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["ef05c1887e5ad95f"] = { "Persino i Windshaper ti direbbero che gli spiriti non hanno mai parlato bene di un essere supremo tra loro. Riconoscevano l'esistenza di un essere chiamato Al'Akir, ma evitavano di invocarne il nome, quasi come se lo temessero.\r\n\nAnche se questo Al'Akir fosse un onnipotente «Signore del Vento», o sovrano degli elementali dell'aria, è affidarsi agli elementali che ci ha cacciati in questo guaio. Ora dobbiamo tirarcene fuori da soli.", "." },
  ["ef0709d61e45b47a"] = { "La terra ti chiama, {name}. Va' da lei, e sappi che i tuoi fratelli sono fieri di te e di tutto ciò che compirai.", "." },
  ["ef15ae231f4d555a"] = { "Portami il libro dopo averlo studiato. Non ti farò la mia domanda finché non mi avrai dato il libro.", "." },
  ["ef1c528be4762235"] = { "Grazie ancora, {name}. Ora mi avvierò verso la strada. Quando puoi, trova Terenthis e digli che siamo riusciti a fuggire.", "." },
  ["ef1f1d75ac197c46"] = { "Il siero richiederà solo pochi minuti di preparazione, {name}.", "." },
  ["ef1f6a60fe2b64cc"] = { "Ancora nessuna traccia dell'ultimo carico di esplosivi.", "." },
  ["ef1fe425724715ab"] = { "Ho bisogno di aiuto per recuperare un pezzo del mio Confessor's Raiment, Al'tabim.", "." },
  ["ef20d755fbc2d72c"] = { "Una compagnia di spiriti affini può essere una forza potente. Krumn ti aiuterà a riuscirci. Lo troverai al centro informazioni civiche di ⟦Thunder Bluff=Picco del Tuono⟧, sul ripiano inferiore accanto agli ascensori.", "." },
  ["ef3ae483eb26b07e"] = { "Noi vede pallone a nord di rovine lassù. Lui porta te in posti lontani.", "." },
  ["ef4adb3e63eb6b03"] = { "Rischio la mia vita e lo libero perché possa dimostrare la sua innocenza. Se potrò, lo aiuterò in ogni modo.", "." },
  ["ef57d928618351df"] = { "%s porta il fucile alla spalla, prende la mira con cura e spara un colpo al bersaglio.", "." },
  ["ef6457b760044a05"] = { "Esatto, è lì vicino al letto. Eh, scusa per il disturbo!", "." },
  ["ef66a2c5f2f2c781"] = { "Lo spirito ti guarda con un senso di completezza e di consapevolezza che prima non aveva.\n\n«Sento come se un grande peso fosse stato tolto dalla mia anima. Presto riposerò in pace per sempre. Ora lo so, e attendo con pazienza quel momento.\n\nGrazie, <straniero/straniera>.»", "." },
  ["ef736420f8abfda2"] = { "Ah, Braenna Flintcrag. Ha le mani magiche, quella. È Braenna la persona da cercare per le questioni da sacerdote.\n\nDovrai andare a nord dai cancelli di ⟦Ironforge=Forgiardente⟧ fino alla Hall of Mysteries. È lì che la troverai.", "." },
  ["ef7550ffd28d04d5"] = { "La ⟦Syndicate=Lega dei Tagliagole⟧ è fatta di un branco di mezze calzette: disorganizzati, incapaci e pigri...", "." },
  ["ef75b103c7e2fadc"] = { "Coraggio, Fizzule!", "." },
  ["ef8ca25944390962"] = { "Io non scappa da {class} come te!", "." },
  ["ef8ffc5cf8a552f1"] = { "Mi chiamo Dran Droffers, e questo qui è quello zuccone di mio figlio Malton. Se ti serve materiale di recupero, o vuoi venderne, siamo noi le persone con cui devi parlare!", "." },
  ["ef90aa8002626bc0"] = { "È più o meno tutto qui. Quando avrai ottenuto il tuo beneficio riposando vicino al fuoco, torna a parlarmi.", "." },
  ["ef9221b47f752493"] = { "Hai saccheggiato i nostri tesori troppo a lungo. Preparati a incontrare la tua tomba d'acqua!", "." },
  ["ef967a3e16f2008a"] = { "Ho visto contadini armati di bastone tenere testa a soldati addestrati. Non sottovalutare mai la forza e l'abilità che servono per maneggiarne uno come si deve.", "." },
  ["ef98cf4e1ff9b7ad"] = { "Khan Jehn era forte, ma stupido. Pensava che la sua forza fosse grande. Non vedeva che la magia della terra è più forte. I centauri Magram ora cadranno senza il loro capo, e un giorno i Gelkis domineranno!", "." },
  ["efa7482dd7478da1"] = { "Altri galoppini del Custode!", "." },
  ["efa869dcd9bc9eec"] = { "Si fa a modo mio, o te ne vai per la ⟦Gold Road=Strada dell'Oro⟧. Chiaro?", "." },
  ["efa9a75f32aebd13"] = { "Ehi, amico! Sei mai andat<o/a> a immergerti in fondo all'oceano? Ti svelo un piccolo segreto, eh. In fondo all'oceano puoi trovare delle fessure gorgoglianti: ti permettono di respirare aria sott'acqua. Ma teniamolo tra noi due, eh. Non mi serve concorrenza per le mie trappole per molluschi da altre parti... se capisci cosa intendo!", "." },
  ["efac364031c33add"] = { "Ah, libertà! Breve, ma così dolce...", "." },
  ["efb0073c3e4fb93c"] = { "Giù di morale? Vieni al Blue Recluse a divertirti!", "." },
  ["efbc01906030ecc5"] = { "Non farti beccare a rubare niente! Cerca Shenthul e la sua Shadowswift Brotherhood nella Cleft of Shadow, sottoterra. Il tunnel che vi scende si trova a sud della Valle della Saggezza.", "." },
  ["efbc74f8f9c80d89"] = { "Insegnami a creare e applicare una ⟦Runecloth Bandage=Benda di Telarunica⟧, dottore.", "." },
  ["efbcb898d7bd298f"] = { "Sì, ma lo troverai più gratificante se sei esperto di Erbalismo! Dovrai curare e coltivare semi speciali. Lo ⟦Evergreen Pouch=Zaino Sempreverde⟧ che riceverai permette anche a un novizio di far crescere qualcosa, ma chi mostra un po' di talento per l'Erbalismo otterrà raccolti più abbondanti.", "." },
  ["efbddc1533965f86"] = { "Spero che Ogron trovi quel pellerosa e gli spezzi le gambe. Vediamo come se la cava nella palude in quello stato!", "." },
  ["efc1f8e715ce3db7"] = { "%s esamina i gusci di snapjaw...", "." },
  ["efcc104f5f9f8282"] = { "Passa a unità esperte!", "." },
  ["efcfc9c47e2b934c"] = { "Be', qui fuori non avrai molta fortuna a trovare un sarto. Però a ⟦Ironforge=Forgiardente⟧ vivono parecchi sarti di talento. Perché non vai a chiedere a una guardia laggiù?", "." },
  ["efd58f4d2355cd25"] = { "Presto, figliolo... molto presto.", "." },
  ["efd6bf8b508f9d97"] = { "Padrona!! Vogliono distruggere la tua opera!!", "." },
  ["efdb059f8879b43d"] = { "Solo una piccola regolazione qui... ah, ecco fatto!", "." },
  ["efdf33c2dfb4a506"] = { "Hai idea di cosa mi tocca passare per portare qui in vendita questi oggetti di valore impareggiabile? Vieni a vederli tutti con i tuoi occhi!", "." },
  ["efe3f67690132401"] = { "Il padrone è caduto! Vendicatelo, fratelli miei!", "." },
  ["eff16076114a68d2"] = { "Questi andranno benissimo, {name}.\n\nIl fuoco è più di caos e distruzione: ricordalo bene. È anche vita e creazione. Tutte le cose sono legate tra loro in questo modo. Le forze si oppongono l'una all'altra ma, allo stesso tempo, l'una non può esistere senza l'altra. Si estinguono a vicenda, ma si danno anche significato a vicenda. Ricordalo sempre.\n\nUsare diversi tipi di magia insieme mostrerà non solo vera abilità, ma grande saggezza.", "." },
  ["eff29705150f030a"] = { "Vedo che hai perso quel capitolo che avevi faticato tanto a mettere insieme, {name}. Be', l'avevi lasciato proprio qui!", "." },
  ["eff770e6803dbb13"] = { "Non ti sei ancora guadagnat<o/a> il diritto di addestrarti con me. Va' prima da Thund, vicino al tavolo. Torna quando lui dirà che sei <pronto/pronta>!", "." },
  ["eff959cfe048bc75"] = { "Come imparerai, il sentiero che percorriamo non è semplice come può sembrare. Mentre cerchiamo di ritrovare la voce necessaria per parlare con gli spiriti dei venti, i venti sono solo una delle forze elementali di questo mondo. Solo comprendendo, e speriamo padroneggiando, tutti e quattro gli elementi ritroveremo la nostra voce per cantare di nuovo i canti del vento.", "." },
  ["eff95d86ef770c34"] = { "Quindi è così che è morto Windsor...", "." },
})
